// Update does not automatically update the record in case of default values. Use .Reload() to refresh the records.
func (o *DirectorySyncRun) Update(ctx context.Context, exec boil.ContextExecutor, columns boil.Columns) (int64, error) {
	var err error
	if err = o.doBeforeUpdateHooks(ctx, exec); err != nil {
		return 0, err
	}
	key := makeCacheKey(columns, nil)
	directorySyncRunUpdateCacheMut.RLock()
	cache, cached := directorySyncRunUpdateCache[key]
	directorySyncRunUpdateCacheMut.RUnlock()

	if !cached {
		wl := columns.UpdateColumnSet(
			directorySyncRunAllColumns,
			directorySyncRunPrimaryKeyColumns,
		)

		if !columns.IsWhitelist() {
			wl = strmangle.SetComplement(wl, []string{"created_at"})
		}
		if len(wl) == 0 {
			return 0, errors.New("dbpostgres: unable to update directory_sync_runs, could not build whitelist")
		}

		cache.query = fmt.Sprintf("UPDATE \"directory_sync_runs\" SET %s WHERE %s",
			strmangle.SetParamNames("\"", "\"", 1, wl),
			strmangle.WhereClause("\"", "\"", len(wl)+1, directorySyncRunPrimaryKeyColumns),
		)
		cache.valueMapping, err = queries.BindMapping(directorySyncRunType, directorySyncRunMapping, append(wl, directorySyncRunPrimaryKeyColumns...))
		if err != nil {
			return 0, err
		}
	}

	values := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(o)), cache.valueMapping)

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, cache.query)
		fmt.Fprintln(writer, values)
	}
	var result sql.Result
	result, err = exec.ExecContext(ctx, cache.query, values...)
	if err != nil {
		return 0, errors.Wrap(err, "dbpostgres: unable to update directory_sync_runs row")
	}

	rowsAff, err := result.RowsAffected()
	if err != nil {
		return 0, errors.Wrap(err, "dbpostgres: failed to get rows affected by update for directory_sync_runs")
	}

	if !cached {
		directorySyncRunUpdateCacheMut.Lock()
		directorySyncRunUpdateCache[key] = cache
		directorySyncRunUpdateCacheMut.Unlock()
	}

	return rowsAff, o.doAfterUpdateHooks(ctx, exec)
}

